var rows = root.querySelectorAll('.trm7-scramble-resolve-val');
var state = root.querySelector('.trm7-scramble-resolve-state');
var fill = root.querySelector('.trm7-scramble-resolve-fill');
if (!rows.length) return;
var pool = 'ABCDEFGHJKLMNPQRSTUVWXYZ0123456789#%&$@<>*+=-';
var targets = [], i;
for (i = 0; i < rows.length; i++) { targets.push(rows[i].textContent); }
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (rm) { if (state) state.textContent = 'RESOLVED'; if (fill) fill.style.width = '100%'; return; }
function rnd() { return pool.charAt(Math.floor(Math.random() * pool.length)); }
function scramble(el, text, dur, done) {
  var start = null;
  function frame(now) {
    if (start === null) start = now;
    var t = (now - start) / dur;
    if (t > 1) t = 1;
    var lock = Math.floor(t * text.length);
    var out = '';
    for (var k = 0; k < text.length; k++) {
      var c = text.charAt(k);
      if (k < lock || c === ' ' || c === '-') out += c;
