function run() {
  if (state) state.textContent = 'RESOLVING';
  if (fill) fill.style.width = '0%';
  var n = 0;
  for (var j = 0; j < rows.length; j++) {
    (function (idx) {
      setTimeout(function () {
        scramble(rows[idx], targets[idx], 640 + idx * 80, function () {
