if (!tracks.length) return;
function flash(el, up) {
  var cls = up ? 'trm7-marquee-ticker-flash-up' : 'trm7-marquee-ticker-flash-dn';
  el.classList.add(cls);
  setTimeout(function () { el.classList.remove(cls); }, 520);
}
function tick() {
  for (var t = 0; t < tracks.length; t++) {
    var nums = tracks[t].querySelectorAll('.trm7-marquee-ticker-num');
    var half = nums.length / 2;
    if (half < 1) continue;
    var i = Math.floor(Math.random() * half);
    var base = parseFloat(nums[i].textContent.replace(/[^0-9.]/g, ''));
    if (isNaN(base)) continue;
    var d = (Math.random() - 0.45) * (base * 0.014 + 0.04);
    var v = base + d;
