    var txt = v.toFixed(2);
    var up = d >= 0;
    var pair = [nums[i], nums[i + half]];
    for (var p = 0; p < pair.length; p++) {
      if (!pair[p]) continue;
      pair[p].textContent = txt;
      flash(pair[p], up);
      var wrap = pair[p].parentNode;
      var chg = wrap ? wrap.querySelector('.trm7-marquee-ticker-chg') : null;
      if (chg) {
        chg.textContent = up ? '▲' : '▼';
