  var all = build(msgs[0]);
  for (var q = 0; q < all.length; q++) all[q].classList.add('trm7-word-reveal-w-on');
  if (cnt) cnt.textContent = pad(all.length) + ' / ' + pad(all.length) + ' words';
  return;
}
var mi = 0;
function run() {
  textEl.classList.remove('trm7-word-reveal-text-out');
  var els = build(msgs[mi % msgs.length]);
  var total = els.length;
  if (cnt) cnt.textContent = '00 / ' + pad(total) + ' words';
  for (var j = 0; j < total; j++) {
    (function (k) {
      setTimeout(function () {
        els[k].classList.add('trm7-word-reveal-w-on');
        if (cnt) cnt.textContent = pad(k + 1) + ' / ' + pad(total) + ' words';
      }, 95 * k);
    })(j);
  }
  setTimeout(function () {
    textEl.classList.add('trm7-word-reveal-text-out');
    setTimeout(function () { mi++; run(); }, 360);
  }, 95 * total + 1700);
}
run();

