var lines = root.querySelectorAll('.trm7-glitch-block-ln');
var scr = root.querySelector('.trm7-glitch-block-scr');
if (!lines.length) return;
var rm = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
if (rm) return;
var orig = [], i;
for (i = 0; i < lines.length; i++) orig.push(lines[i].textContent);
var junk = '▓▒░#%&@!?<>*+=~^';
function corrupt() {
  var idx = Math.floor(Math.random() * lines.length);
  var s = orig[idx];
  var hits = 1 + Math.floor(Math.random() * 4);
  var pos = {}, h, k, out = '';
  for (h = 0; h < hits; h++) pos[Math.floor(Math.random() * s.length)] = 1;
  for (k = 0; k < s.length; k++) {
    out += pos[k] ? junk.charAt(Math.floor(Math.random() * junk.length)) : s.charAt(k);
  }
  var el = lines[idx];
  el.textContent = out;
  el.classList.add('trm7-glitch-block-hot');
  setTimeout(function () {
    el.textContent = orig[idx];
    el.classList.remove('trm7-glitch-block-hot');
  }, 110 + Math.random() * 170);
}
function loop() {
  corrupt();
  if (scr && Math.random() < 0.3) {
    scr.classList.add('trm7-glitch-block-jolt');
    setTimeout(function () { scr.classList.remove('trm7-glitch-block-jolt'); }, 130);
  }
  setTimeout(loop, 240 + Math.random() * 720);
}
loop();

