js:
var digits = root.querySelectorAll('.trm7-segment-countdown-digit');
var st = root.querySelector('.trm7-segment-countdown-st');
if (!digits.length) return;
var MAP = { '0': 'abcdef', '1': 'bc', '2': 'abdeg', '3': 'abcdg', '4': 'bcfg', '5': 'acdfg', '6': 'acdefg', '7': 'abc', '8': 'abcdefg', '9': 'abcdfg' };
var START = 2 * 3600 + 47 * 60 + 12;
var total = START;
function setDigit(d, ch) {
  var on = MAP[ch] || '';
  var segs = d.querySelectorAll('.trm7-segment-countdown-s');
  for (var i = 0; i < segs.length; i++) {
    var L = 'abcdefg'.charAt(i);
    if (on.indexOf(L) > -1) segs[i].classList.add('trm7-segment-countdown-on');
    else segs[i].classList.remove('trm7-segment-countdown-on');
  }
}
function render() {
  var h = Math.floor(total / 3600), m = Math.floor((total % 3600) / 60), s = total % 60;
  var str = (h < 10 ? '0' : '') + h + (m < 10 ? '0' : '') + m + (s < 10 ? '0' : '') + s;
  for (var i = 0; i < digits.length && i < 6; i++) setDigit(digits[i], str.charAt(i));
  if (st) st.textContent = total <= 60 ? 'FINAL' : 'ARMED';
  if (total <= 60) root.classList.add('trm7-segment-countdown-crit');
  else root.classList.remove('trm7-segment-countdown-crit');
}
render();
setInterval(function () {
  total--;
  if (total < 0) total = START;
  render();
}, 1000);
